var documenterSearchIndex = {"docs":
[{"category":"section","location":"generated/02_ei_network/#One-excitatory-and-one-inhibitory-unit","page":"One excitatory and one inhibitory unit","text":"This example considers two mutually connected units: one excitatory and one inhibitory. Each postsynaptic unit receives a connection from both units, for a total of four connections.","title":"One excitatory and one inhibitory unit"},{"category":"section","location":"generated/02_ei_network/#Initialization","page":"One excitatory and one inhibitory unit","text":"using LinearAlgebra\nusing Plots\nusing Random\nRandom.seed!(0)\n\nusing HawkesPlasticNetworks; global const H = HawkesPlasticNetworks","title":"Initialization"},{"category":"section","location":"generated/02_ei_network/#Define-the-parameters","page":"One excitatory and one inhibitory unit","text":"τ_kernel = [20.0,10.0]\nweights = [1.3 -1.2; 1.2 -1.0]\ninput = [40.0,10.0]\nsimulation_end = 1_000.0\nbin_width = 10.0\n\nThe matrix uses post <- pre ordering. Its first column is excitatory and its second column is inhibitory. Connections store only positive magnitudes; the presynaptic population type determines whether a contribution is added or subtracted.\n\nto_matrix(x::Real) = cat(x;dims=2)\n\nweight_exc_exc = to_matrix(abs(weights[1,1]))\nweight_exc_inh = to_matrix(abs(weights[1,2]))\nweight_inh_exc = to_matrix(abs(weights[2,1]))\nweight_inh_inh = to_matrix(abs(weights[2,2]))\n\nexpected_rates = (I-weights)\\input\n\nprintln(\"Expected excitatory rate: \",expected_rates[1])\nprintln(\"Expected inhibitory rate: \",expected_rates[2])\n\n#","title":"Define the parameters"},{"category":"section","location":"generated/02_ei_network/#Define-the-populations-and-connections","page":"One excitatory and one inhibitory unit","text":"population_exc = H.PopulationExpKernelExcitatory(\n    1,τ_kernel[1];label=\"exc\")\npopulation_inh = H.PopulationExpKernelInhibitory(\n    1,τ_kernel[2];label=\"inh\")\n\nconnection_exc_exc = H.ConnectionWithWeights(\n    population_exc,weight_exc_exc,population_exc)\nconnection_exc_inh = H.ConnectionWithWeights(\n    population_exc,weight_exc_inh,population_inh)\nconnection_inh_exc = H.ConnectionWithWeights(\n    population_inh,weight_inh_exc,population_exc)\nconnection_inh_inh = H.ConnectionWithWeights(\n    population_inh,weight_inh_inh,population_inh)\n\nconnected_exc = H.ConnectedPopulationExpKernel(\n    population_exc,[input[1]],\n    (connection_exc_exc,population_exc),\n    (connection_exc_inh,population_inh))\nconnected_inh = H.ConnectedPopulationExpKernel(\n    population_inh,[input[2]],\n    (connection_inh_exc,population_exc),\n    (connection_inh_inh,population_inh))","title":"Define the populations and connections"},{"category":"section","location":"generated/02_ei_network/#Record-the-population-rates","page":"One excitatory and one inhibitory unit","text":"rec_rate_exc = H.RecorderPopulationRate(\n    population_exc,simulation_end;Δt=bin_width)\nrec_rate_inh = H.RecorderPopulationRate(\n    population_inh,simulation_end;Δt=bin_width)\n\nnetwork = H.RecurrentNetworkExpKernel(\n    (connected_exc,connected_inh),(rec_rate_exc,rec_rate_inh))","title":"Record the population rates"},{"category":"section","location":"generated/02_ei_network/#Run-the-simulation","page":"One excitatory and one inhibitory unit","text":"function run_simulation!(network,simulation_end)\n  t_now = 0.0\n  H.reset!(network)\n  while t_now < simulation_end\n    t_now = H.dynamics_step!(t_now,network)\n  end\n  return t_now\nend\n\nlast_spike_time = run_simulation!(network,simulation_end)\nrate_exc = H.get_content(rec_rate_exc)\nrate_inh = H.get_content(rec_rate_inh)","title":"Run the simulation"},{"category":"section","location":"generated/02_ei_network/#Convergence-toward-the-expected-rates","page":"One excitatory and one inhibitory unit","text":"my_line_width=2\n\nplot_exc = plot(\n    rate_exc.times,rate_exc.rates;\n    label=\"$(bin_width) s binned rate\",color=:blue,linewidth=my_line_width,\n    xlabel=\"\",ylabel=\"excitatory rate (Hz)\",\n    ylim=(0,1.1maximum(rate_exc.rates)))\nhline!(\n    plot_exc,[expected_rates[1]];\n    label=\"expected rate\",color=:grey,linestyle=:dash,linewidth=2)\n\nplot_inh = plot(\n    rate_inh.times,rate_inh.rates;\n    label=\"$(bin_width) s binned rate\",color=:red,linewidth=my_line_width,\n    xlabel=\"time (s)\",ylabel=\"inhibitory rate (Hz)\",\n    ylim=(0,1.1maximum(rate_inh.rates)))\nhline!(\n    plot_inh,[expected_rates[2]];\n    label=\"expected rate\",color=:grey,linestyle=:dash,linewidth=2)\n\nplot(plot_exc,plot_inh;layout=(2,1),size=(800,600))\n\n\n\nThis page was generated using Literate.jl.","title":"Convergence toward the expected rates"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Stabilization-of-large-E/I-recurrent-networks-through-homeostatic-plasticity","page":"Homeostatic stabilization","text":"In this example, I show how two flavors of homeostatic inhibitory-to-excitatory plasticity can stabilize a large E/I network, so that the exc population reaches a target firing rate determined below.","title":"Stabilization of large E/I recurrent networks through homeostatic plasticity"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Initialization","page":"Homeostatic stabilization","text":"using Random\nusing Statistics\n\n\nusing Distributions\nusing Plots, Colors\nRandom.seed!(0)\n\nusing HawkesPlasticNetworks; global const H = HawkesPlasticNetworks","title":"Initialization"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Define-the-parameters","page":"Homeostatic stabilization","text":"ne = 100       # number of excitatory neurons\nni = 20        # number of inhibitory neurons\nτ_e = 20E-3    # time constant for excitatory neurons\nτ_i = 10E-3    # time constant for inhibitory neurons\n\nn_spikes = 2_000_000  # total number of spikes to simulate (for all neurons!)\n\nw_ee = 1.295       # excitatory-to-excitatory connection weight\nw_ie = 1.2         # excitatory-to-inhibitory connection weight\nw_ei_example = 1.2 # inhibitory-to-excitatory connection weight (this will actually come from plasticity)\nw_ii = 1.0         # inhibitory-to-inhibitory connection weight\n\nh_e = 40.0     # external input to excitatory neurons\nh_i = 10.0     # external input to inhibitory neurons\n\np_ee = 0.4     # sparseness for E->E\np_ei = 1.0     # sparseness for I->E\np_ie = 0.6     # sparseness for E->I\np_ii = 0.8     # sparseness for I->I\n\nbin_width = 5.0 # bin width for rate recording\n\nn_tot = ne + ni\nidx_e = 1:ne\nidx_i = ne+1:n_tot;\nnothing #hide","title":"Define the parameters"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Check-the-expected-rates","page":"Homeostatic stabilization","text":"rate_example_e,rate_example_i = H.expected_rate_EI(\n    w_ee,w_ie,w_ei_example,w_ii,\n    h_e,h_i)\n\nre_target = rate_example_e # the target rate will be the same we calculate here\nri_target = rate_example_i\n\nprintln(\"Expected excitatory rate: \",round(rate_example_e;digits=2))\nprintln(\"Expected inhibitory rate: \",round(rate_example_i;digits=2))","title":"Check the expected rates"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Create-expanded-weight-matrices","page":"Homeostatic stabilization","text":"wmat_ee = H.generate_sparse_matrix_fixed_input(ne,ne,w_ee,p_ee;self_connections=false)\nwmat_ie = H.generate_sparse_matrix_fixed_input(ni,ne,w_ie,p_ie)\nwmat_ii = H.generate_sparse_matrix_fixed_input(\n    ni,ni,w_ii,p_ii;self_connections=false);\nnothing #hide\n\nWe still need to initialize wmat_ei, the plastic part let's use a very weak long-tailed distribution for the weights with this choice, we expect the network to be unstable at first\n\nwmat_ei_start = H.generate_sparse_matrix_fixed_input(ne,ni,0.01,p_ei);\nei_distr = Exponential(3.0)\nfor i in eachindex(wmat_ei_start)\n  if wmat_ei_start[i] != 0.0\n    wmat_ei_start[i] *= rand(ei_distr)\n  end\nend\nei_connection_mask = .!iszero.(wmat_ei_start);\nnothing #hide\n\nAnd a full version for plotting purposes\n\nwmat_full_start = Matrix{Float64}(undef,n_tot,n_tot)\nwmat_full_start[idx_e,idx_e] = wmat_ee\nwmat_full_start[idx_e,idx_i] = .- wmat_ei_start\nwmat_full_start[idx_i,idx_e] = wmat_ie\nwmat_full_start[idx_i,idx_i] = .- wmat_ii\n\nfunction do_colormap(minval::Real,maxval::Real;\n    cminus=:red,czero=:white,cplus=:blue,\n    ncolors::Integer=500)\n  if minval >= 0\n    return cgrad([czero,cplus], [0,1])\n  end\n  if maxval <= 0\n    return cgrad([cminus,czero], [0,1])\n  end\n  _mid = minval/(minval-maxval)\n  vcols = [cminus,fill(czero,ncolors-2)...,cplus]\n  midrange = range(_mid-1E-10,_mid+1E-10,length=ncolors-2)\n  vals = [0.,midrange...,1.]\n  return cgrad(vcols,vals)\nend\n\nfunction Wplot(W::Matrix{<:Real},bounds::Tuple{<:Real,<:Real}=extrema(W);\n    title::String=\"\")\n  N=size(W,1)\n  _cmap = do_colormap(bounds...)\n  return heatmap(W;ratio=1,\n    xlims=(0,N).+0.5,\n    ylims=(0,N).+0.5,\n    xlabel=\"pre\",\n    ylabel=\"post\",\n    color=_cmap,\n    clims=bounds,\n    title=title)\nend;\nnothing #hide\n\nWplot(wmat_full_start;title=\"Initial recurrent weights\")","title":"Create expanded weight matrices"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Network-1,-Vogels-Sprekeler-rate-homeostatic-rule","page":"Homeostatic stabilization","text":"Plasticity parameters\n\nτplast = 20E-3 # time constant in line with the kernel\nηplast = 1E-7; # learning rate\nnothing #hide\n\nDefine populations, one excitatory one inhibitory\n\npopulation_exc = H.PopulationExpKernelExcitatory(\n    ne,τ_e;label=\"exc\")\npopulation_inh = H.PopulationExpKernelInhibitory(\n    ni,τ_i;label=\"inh\");\nnothing #hide\n\nDefine fixed connections\n\nconnection_ee = H.ConnectionWithWeights(\n    population_exc,wmat_ee,population_exc)\nconnection_ie = H.ConnectionWithWeights(\n    population_inh,wmat_ie,population_exc)\nconnection_ii = H.ConnectionWithWeights(\n    population_inh,wmat_ii,population_inh);\nnothing #hide\n\nNow the plasticity rule for the inhibitory-to-excitatory weights\n\nplast_vog_sprek = H.PlasticityVogelsSprekeler(ηplast,\n  re_target,τplast,wmat_ei_start;\n  weight_min=0.0);\n\nconnection_ei = H.ConnectionWithWeights(\n    population_exc,wmat_ei_start,population_inh;\n    plasticity_rules=(plast_vog_sprek,))\n\nconnected_exc = H.ConnectedPopulationExpKernel(\n    population_exc,fill(h_e,ne),\n    (connection_ee,population_exc),\n    (connection_ei,population_inh))\nconnected_inh = H.ConnectedPopulationExpKernel(\n    population_inh,fill(h_i,ni),\n    (connection_ie,population_exc),\n    (connection_ii,population_inh));\nnothing #hide","title":"Network 1, Vogels-Sprekeler rate homeostatic rule"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Record-the-population-rates-and-weights","page":"Homeostatic stabilization","text":"Rate recorders allocate their bins in advance. I expect the network to be unstable at first, so I set a very long recorder duration.\n\ntarget_total_rate = ne*re_target + ni*ri_target\nt_end_recorders = 100.0*n_spikes/target_total_rate\n\nrec_rate_exc = H.RecorderPopulationRate(\n    population_exc,t_end_recorders;Δt=bin_width)\nrec_rate_inh = H.RecorderPopulationRate(\n    population_inh,t_end_recorders;Δt=bin_width)\n\nrec_w_ei = H.WeightMatrixRecorder(\n    connection_ei.weights,bin_width,t_end_recorders)\n\nnetwork = H.RecurrentNetworkExpKernel(\n    (connected_exc,connected_inh),\n    (rec_rate_exc,rec_rate_inh,rec_w_ei));\nnothing #hide","title":"Record the population rates and weights"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Run-the-simulation","page":"Homeostatic stabilization","text":"function run_simulation!(network,n_spikes)\n  t_now = 0.0\n  H.reset!(network)\n  H.set_initial_rates!(connected_exc,h_e)\n  H.set_initial_rates!(connected_inh,h_i)\n  for _ in 1:n_spikes\n    t_now = H.dynamics_step!(t_now,network)\n  end\n  return t_now\nend\n\nlast_spike_time = run_simulation!(network,n_spikes)\nprintln(\"Network run completed!\")\nprintln(\"Last spike time: \",round(last_spike_time;digits=2),\" s\")\n\nrates_exc = H.get_content(rec_rate_exc)\nrates_inh = H.get_content(rec_rate_inh)\nweights_ei_content = H.get_content(rec_w_ei);\nnothing #hide","title":"Run the simulation"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Convergence-toward-the-target-rates","page":"Homeostatic stabilization","text":"my_line_width = 2\n\nplot_exc = plot(\n    rates_exc.times,rates_exc.rates;\n    label=\"$(bin_width) s binned rate\",color=:blue,\n    linewidth=my_line_width,xlabel=\"\",ylabel=\"excitatory rate (Hz)\",\n    xlims=(0,maximum(rates_exc.times)),\n    ylims=(0,maximum(rates_exc.rates)*1.1),\n    legend=:bottomright)\nhline!(\n    plot_exc,[re_target];\n    label=\"target rate\",color=:grey,linestyle=:dash,linewidth=2)\n\nplot_inh = plot(\n    rates_inh.times,rates_inh.rates;\n    label=\"$(bin_width) s binned rate\",color=:red,\n    linewidth=my_line_width,xlabel=\"time (s)\",\n    ylabel=\"inhibitory rate (Hz)\",\n    xlims=(0,maximum(rates_inh.times)),\n    ylims=(0,maximum(rates_inh.rates)*1.1),\n    legend=:bottomright)\nhline!(\n    plot_inh,[ri_target];\n    label=\"target rate\",color=:grey,linestyle=:dash,linewidth=2)\n\nplot(plot_exc,plot_inh;layout=(2,1),size=(800,600))","title":"Convergence toward the target rates"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Evolution-of-inhibitory-to-excitatory-weights","page":"Homeostatic stabilization","text":"Structural zeros represent absent connections and are excluded from the summary. The shaded region spans the 0.25 to 0.75 quantiles.\n\nn_weight_times = length(weights_ei_content.times)\nweights_ei_connected = reshape(\n    weights_ei_content.weights,n_weight_times,:)[:,vec(ei_connection_mask)]\nmean_weights_ei = vec(mean(weights_ei_connected;dims=2))\nquantiles_weights_ei = reduce(\n    hcat,quantile(row,[0.25,0.75]) for row in eachrow(weights_ei_connected))\nlower_weights_ei = vec(quantiles_weights_ei[1,:])\nupper_weights_ei = vec(quantiles_weights_ei[2,:])\n\nplot(\n    weights_ei_content.times,mean_weights_ei;\n    ribbon=(\n        mean_weights_ei .- lower_weights_ei,\n        upper_weights_ei .- mean_weights_ei),\n    fillalpha=0.25,\n    label=\"mean with 0.25–0.75 quantiles\",\n    color=:purple,\n    linewidth=my_line_width,\n    xlabel=\"time (s)\",\n    ylabel=\"inhibitory-to-excitatory weight\",\n    xlims=(0,maximum(weights_ei_content.times)),\n    legend=:bottomright)\nhline!(\n    [w_ei_example/ni]; # the expected is the sum over inhibitory inputs, so must divide to match single avg weight\n    label=\"expected weight\",color=:grey,linestyle=:dash,linewidth=2)","title":"Evolution of inhibitory-to-excitatory weights"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Recurrent-weights-after-training","page":"Homeostatic stabilization","text":"wmat_full_after_training = copy(wmat_full_start)\nwmat_full_after_training[idx_e,idx_i] = .-connection_ei.weights\n\nWplot(wmat_full_after_training;title=\"Recurrent weights after training\")\n\nwow, much blanket!","title":"Recurrent weights after training"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Network-2,-homeostatic-scaling","page":"Homeostatic stabilization","text":"s_hom = +1    # +1 for inhibitory presynaptic neuron (like here) -1 for excitatory presynaptic neuron\nτ_hom = 10.0  # long timescale for rate integration\nη_hom = 1E-4; # multiplicative learning rate\nnothing #hide\n\nDefine fresh populations and connections so that this simulation starts from the same state as the Vogels-Sprekeler simulation.\n\npopulation_exc_stdhs = H.PopulationExpKernelExcitatory(\n    ne,τ_e;label=\"exc_stdhs\")\npopulation_inh_stdhs = H.PopulationExpKernelInhibitory(\n    ni,τ_i;label=\"inh_stdhs\");\n\nconnection_ee_stdhs = H.ConnectionWithWeights(\n    population_exc_stdhs,wmat_ee,population_exc_stdhs)\nconnection_ie_stdhs = H.ConnectionWithWeights(\n    population_inh_stdhs,wmat_ie,population_exc_stdhs)\nconnection_ii_stdhs = H.ConnectionWithWeights(\n    population_inh_stdhs,wmat_ii,population_inh_stdhs);\nnothing #hide\n\nRecover the initial positive E<-I weights from the full matrix.\n\nwmat_ei_start_stdhs = .-copy(wmat_full_start[idx_e,idx_i])\nplast_stdhs = H.PlasticityHomeostaticScaling(\n    η_hom,re_target,s_hom,τ_hom,wmat_ei_start_stdhs;\n    weight_min=0.0)\n\nconnection_ei_stdhs = H.ConnectionWithWeights(\n    population_exc_stdhs,wmat_ei_start_stdhs,population_inh_stdhs;\n    plasticity_rules=(plast_stdhs,))\n\nconnected_exc_stdhs = H.ConnectedPopulationExpKernel(\n    population_exc_stdhs,fill(h_e,ne),\n    (connection_ee_stdhs,population_exc_stdhs),\n    (connection_ei_stdhs,population_inh_stdhs))\nconnected_inh_stdhs = H.ConnectedPopulationExpKernel(\n    population_inh_stdhs,fill(h_i,ni),\n    (connection_ie_stdhs,population_exc_stdhs),\n    (connection_ii_stdhs,population_inh_stdhs));\nnothing #hide","title":"Network 2, homeostatic scaling"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Record-the-population-rates-and-weights-2","page":"Homeostatic stabilization","text":"rec_rate_exc_stdhs = H.RecorderPopulationRate(\n    population_exc_stdhs,t_end_recorders;Δt=bin_width)\nrec_rate_inh_stdhs = H.RecorderPopulationRate(\n    population_inh_stdhs,t_end_recorders;Δt=bin_width)\nrec_w_ei_stdhs = H.WeightMatrixRecorder(\n    connection_ei_stdhs.weights,bin_width,t_end_recorders)\n\nnetwork_stdhs = H.RecurrentNetworkExpKernel(\n    (connected_exc_stdhs,connected_inh_stdhs),\n    (rec_rate_exc_stdhs,rec_rate_inh_stdhs,rec_w_ei_stdhs));\nnothing #hide","title":"Record the population rates and weights"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Run-the-simulation-2","page":"Homeostatic stabilization","text":"function run_simulation_stdhs!(network,n_spikes)\n  t_now = 0.0\n  H.reset!(network)\n  H.set_initial_rates!(connected_exc_stdhs,h_e)\n  H.set_initial_rates!(connected_inh_stdhs,h_i)\n  plast_stdhs.trace_post.val .= re_target\n  plast_stdhs.trace_post.t_last = 0.0\n  for _ in 1:n_spikes\n    t_now = H.dynamics_step!(t_now,network)\n  end\n  return t_now\nend\n\nlast_spike_time_stdhs = run_simulation_stdhs!(network_stdhs,n_spikes)\nprintln(\"STDHS network run completed!\")\nprintln(\n    \"Last spike time: \",round(last_spike_time_stdhs;digits=2),\" s\")\n\nrates_exc_stdhs = H.get_content(rec_rate_exc_stdhs)\nrates_inh_stdhs = H.get_content(rec_rate_inh_stdhs)\nweights_ei_content_stdhs = H.get_content(rec_w_ei_stdhs);\nnothing #hide","title":"Run the simulation"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Convergence-toward-the-target-rates-2","page":"Homeostatic stabilization","text":"plot_exc_stdhs = plot(\n    rates_exc_stdhs.times,rates_exc_stdhs.rates;\n    label=\"$(bin_width) s binned rate\",color=:blue,\n    linewidth=my_line_width,xlabel=\"\",ylabel=\"excitatory rate (Hz)\",\n    xlims=(0,maximum(rates_exc_stdhs.times)),\n    ylims=(0,maximum(rates_exc_stdhs.rates)*1.1),\n    legend=:bottomright)\nhline!(\n    plot_exc_stdhs,[re_target];\n    label=\"target rate\",color=:grey,linestyle=:dash,linewidth=2)\n\nplot_inh_stdhs = plot(\n    rates_inh_stdhs.times,rates_inh_stdhs.rates;\n    label=\"$(bin_width) s binned rate\",color=:red,\n    linewidth=my_line_width,xlabel=\"time (s)\",\n    ylabel=\"inhibitory rate (Hz)\",\n    xlims=(0,maximum(rates_inh_stdhs.times)),\n    ylims=(0,maximum(rates_inh_stdhs.rates)*1.1),\n    legend=:bottomright)\nhline!(\n    plot_inh_stdhs,[ri_target];\n    label=\"target rate\",color=:grey,linestyle=:dash,linewidth=2)\n\nplot(plot_exc_stdhs,plot_inh_stdhs;layout=(2,1),size=(800,600))","title":"Convergence toward the target rates"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Evolution-of-inhibitory-to-excitatory-weights-2","page":"Homeostatic stabilization","text":"n_weight_times_stdhs = length(weights_ei_content_stdhs.times)\nweights_ei_connected_stdhs = reshape(\n    weights_ei_content_stdhs.weights,n_weight_times_stdhs,:)[:,\n    vec(ei_connection_mask)]\nmean_weights_ei_stdhs = vec(mean(weights_ei_connected_stdhs;dims=2))\nquantiles_weights_ei_stdhs = reduce(\n    hcat,\n    quantile(row,[0.25,0.75])\n    for row in eachrow(weights_ei_connected_stdhs))\nlower_weights_ei_stdhs = vec(quantiles_weights_ei_stdhs[1,:])\nupper_weights_ei_stdhs = vec(quantiles_weights_ei_stdhs[2,:])\n\nplot(\n    weights_ei_content_stdhs.times,mean_weights_ei_stdhs;\n    ribbon=(\n        mean_weights_ei_stdhs .- lower_weights_ei_stdhs,\n        upper_weights_ei_stdhs .- mean_weights_ei_stdhs),\n    fillalpha=0.25,\n    label=\"mean with 0.25–0.75 quantiles\",\n    color=:purple,\n    linewidth=my_line_width,\n    xlabel=\"time (s)\",\n    ylabel=\"inhibitory-to-excitatory weight\",\n    xlims=(0,maximum(weights_ei_content_stdhs.times)),\n    legend=:bottomright)\nhline!(\n    [w_ei_example/ni];\n    label=\"expected weight\",color=:grey,linestyle=:dash,linewidth=2)","title":"Evolution of inhibitory-to-excitatory weights"},{"category":"section","location":"generated/03_homeostatic_stabilization/#Recurrent-weights-after-training-2","page":"Homeostatic stabilization","text":"wmat_full_after_stdhs = copy(wmat_full_start)\nwmat_full_after_stdhs[idx_e,idx_i] = .-connection_ei_stdhs.weights\n\nWplot(wmat_full_after_stdhs;title=\"Recurrent weights after STDHS training\")\n\nLook! It's sparse!\n\n\n\nThis page was generated using Literate.jl.","title":"Recurrent weights after training"},{"category":"section","location":"generated/01_single_unit/#Single-self-interacting-unit","page":"Single self-interacting unit","text":"This example considers the simplest non-trivial configuration: a single unit interacting with itself, without plasticity.","title":"Single self-interacting unit"},{"category":"section","location":"generated/01_single_unit/#Initialization","page":"Single self-interacting unit","text":"using Random\nusing Statistics\nusing Plots\nRandom.seed!(0)\n\nusing HawkesPlasticNetworks; global const H = HawkesPlasticNetworks;\nnothing #hide","title":"Initialization"},{"category":"section","location":"generated/01_single_unit/#Define-the-parameters","page":"Single self-interacting unit","text":"n_units = 1           # one unit only\nτ_kernel = 10.0       # timescale for membrane dynamics\nw_self = 0.8          # self connection weights\nh_in = 20.0           # input current\ninitial_rate = 0.0    # initial rate\nn_spikes = 60_000     # total spikes in the simulation\nbin_width = 2.0       # width for the rate average\n\nFor a stable linear Hawkes process with a normalized exponential kernel, the stationary rate is h_in / (1 - w_self).\n\ntheoretical_rate = h_in/(1-w_self)\nprintln(\"Theoretical rate $(round(theoretical_rate,digits=2)) Hz\")","title":"Define the parameters"},{"category":"section","location":"generated/01_single_unit/#Define-the-population-and-connection","page":"Single self-interacting unit","text":"population = H.PopulationExpKernelExcitatory(\n    n_units,τ_kernel; label=\"unit\");\nnothing #hide\n\nthe connection has the one-neuron population connected to itself\n\nconnection = H.ConnectionWithWeights(\n    population,fill(w_self,n_units,n_units),population);\nnothing #hide\n\nImportant to define the network, you need connected populations. This requires to re-define the connection structure for each population in the simulation. The inputs are:\n\nH.ConnectedPopulationExpKernel(populationpost,inputspost,(connection1,populationpre1),  (connection2,populationpre2),...,(connectionn,populationpre_n))\n\nThe argument order is always post-synaptic first, then pre-synaptic.\n\nconnected_population = H.ConnectedPopulationExpKernel(\n    population,fill(h_in,n_units),(connection,population))","title":"Define the population and connection"},{"category":"section","location":"generated/01_single_unit/#Record-the-spike-train-and-mean-firing-rate","page":"Single self-interacting unit","text":"rec_fulltrain = H.RecorderPopulationTrain(\n    population.label,n_spikes)\n\nRate recorders allocate their bins in advance. Twice the expected duration leaves ample room for this seeded example.\n\nrate_recording_end = 2*n_spikes/theoretical_rate\nrec_binnedrate = H.RecorderPopulationRate(\n    population,rate_recording_end; Δt=bin_width)","title":"Record the spike train and mean firing rate"},{"category":"section","location":"generated/01_single_unit/#Define-the-network","page":"Single self-interacting unit","text":"network = H.RecurrentNetworkExpKernel(\n    (connected_population,),(rec_fulltrain,rec_binnedrate))","title":"Define the network"},{"category":"section","location":"generated/01_single_unit/#Run-the-simulation","page":"Single self-interacting unit","text":"function run_simulation!(network,n_spikes,initial_rate)\n  t_now = 0.0\n  H.reset!(network)\n  H.set_initial_rates!(connected_population,initial_rate)\n  for _ in 1:n_spikes\n    t_now = H.dynamics_step!(t_now,network)\n  end\n  return t_now\nend\n\nlast_spike_time = run_simulation!(network,n_spikes,initial_rate)\ntrain = H.get_content(rec_fulltrain)\nbinned_rate = H.get_content(rec_binnedrate)\n\nempirical_rate = train.n_recorded_spikes/last_spike_time\nreached_bins = binned_rate.times .< last_spike_time\n\n(; theoretical_rate,empirical_rate,last_spike_time,\n   n_recorded_spikes=train.n_recorded_spikes,\n   mean_binned_rate=mean(binned_rate.rates[reached_bins]))","title":"Run the simulation"},{"category":"section","location":"generated/01_single_unit/#Relaxation-toward-the-asymptotic-rate","page":"Single self-interacting unit","text":"The trace starts at initial_rate, while the external input makes the initial conditional intensity h_in + w_self * initial_rate. Its expected value relaxes with time constant τ_kernel/(1-w_self).\n\ninitial_intensity = h_in + w_self*initial_rate\nrelaxation_time = τ_kernel/(1-w_self)\nexpected_rate(t) = theoretical_rate +\n    (initial_intensity-theoretical_rate)*exp(-t/relaxation_time)\n\nplot_end = 8*relaxation_time\nidx_plot = reached_bins .& (binned_rate.times .<= plot_end)\nplot(\n    binned_rate.times[idx_plot],binned_rate.rates[idx_plot];\n    label=\"$(bin_width) s binned rate\",color=:steelblue,alpha=1.0,\n    xlabel=\"time (s)\",ylabel=\"rate (Hz)\",ylim=(0,1.5theoretical_rate))\nplot!(\n    t -> expected_rate(t),0,plot_end;\n    label=\"expected relaxation\",color=:grey,linewidth=2,\n    alpha=0.6)\nhline!(\n    [theoretical_rate];\n    label=\"asymptotic rate\",color=:firebrick,linestyle=:dash,linewidth=2)\n\n\n\nThis page was generated using Literate.jl.","title":"Relaxation toward the asymptotic rate"},{"category":"section","location":"#Hawkes-Plastic-Networks","page":"Home","text":"(Image: )\n\nwarning: Warning\nHawkesPlasticNetworks.jl is at an early stage. Its API may change as the supported model set grows.\n\nHawkesPlasticNetworks.jl provides explicit building blocks for simulating spiking networks driven by Hawkes processes. Start with the worked example below; the API index lists the currently available components.","title":"Hawkes Plastic Networks"},{"category":"section","location":"#Examples","page":"Home","text":"Single self-interacting unit\nOne exc, one inhibitory unit\nInhibitory homeostatic plasticity","title":"Examples"},{"category":"section","location":"#Index","page":"Home","text":"","title":"Index"},{"category":"type","location":"#HawkesPlasticNetworks.AbstractConnectionWithWeights","page":"Home","text":"Supertype for connections that store a weight matrix and plasticity rules.\n\n\n\n\n\n","title":"HawkesPlasticNetworks.AbstractConnectionWithWeights"},{"category":"type","location":"#HawkesPlasticNetworks.ConnectionNonInteracting","page":"Home","text":"Weighted connection that participates in plasticity but transmits no signal.\n\n\n\n\n\n","title":"HawkesPlasticNetworks.ConnectionNonInteracting"},{"category":"type","location":"#HawkesPlasticNetworks.PlasticityAsymmetricSTDP","page":"Home","text":"PlasticityAsymmetricSTDP(\n    η::Real, B::Real, αpre::Real, αpost::Real,\n    τ_plus::Real, γ::Real, weights::Matrix{Float64};\n    weight_min::Real=0.0, weight_max::Real=Inf)\n\nConstruct an asymmetric pair-based STDP rule for weights, whose shape is n_post × n_pre. Positions that are exactly zero at construction are not  changed by plasticity. Use refresh_mask!  to update the plastic synapses.\n\nη is the global learning rate: it scales all terms of plasticity\n\nB controls the balance between potentiation and depression, it must be in the range [-1,1], and is defined as\n\nB = 1 : pure potentiation\nB = -1 : pure depression\nB = 0 : symmetric potentiation and depression\n\nαpre and αpost are the rate constants, applied at  each pre- and post-synaptic spike, respectively.\n\nτ_plus sets the time constant for potentiation.\n\nγ sets the relative time constant for depression γ τ_plus.\n\n\n\n\n\n","title":"HawkesPlasticNetworks.PlasticityAsymmetricSTDP"},{"category":"type","location":"#HawkesPlasticNetworks.PlasticityHomeostaticScaling","page":"Home","text":"PlasticityHomeostaticScaling(\n    η::Real,\n    α::Real,\n    s::Real,\n    τ::Real,\n    weights::Matrix{Float64};\n    weight_min::Real=0.0, weight_max::Real=Inf)\n\nConstructs the homeostatic scaling rule (STDHS) for weights. Positions that are exactly zero at construction are not changed by plasticity. Use refresh_mask! to update the plastic synapses.\n\nη is the global learning rate: it scales all terms of plasticity\n\nα is the target rate in isolation.\n\ns should be +1 for presynaptic inhibitory populations and -1 for presynaptic excitatory populations.\n\nτ sets the time constant\n\n\n\n\n\n","title":"HawkesPlasticNetworks.PlasticityHomeostaticScaling"},{"category":"type","location":"#HawkesPlasticNetworks.PlasticitySymmetricSTDP","page":"Home","text":"PlasticitySymmetricSTDP(\n    η::Real, B::Real, αpre::Real, αpost::Real,\n    τ_plus::Real, γ::Real, weights::Matrix{Float64};\n    weight_min::Real=0.0, weight_max::Real=Inf)\n\nConstruct a symmetric STDP rule for weights, whose shape is n_post × n_pre. Positions that are exactly zero at construction are not changed by plasticity. Use refresh_mask! to update the plastic synapses.\n\nThe rule stores positive and negative traces for both populations. A presynaptic spike combines the two postsynaptic traces, while a postsynaptic spike combines the two presynaptic traces:\n\nDelta w_ij^mathrmpre =\netaleftalpha_mathrmpre +\nA_+ x_imathrmpost^+ + A_- x_imathrmpost^-right\n\nDelta w_ij^mathrmpost =\netaleftalpha_mathrmpost +\nA_+ x_jmathrmpre^+ + A_- x_jmathrmpre^-right\n\nwhere i is the postsynaptic index, j is the presynaptic index, A_plus = (B + 1) / 2, and A_minus = (B - 1) / 2.\n\nη is the global learning rate: it scales all terms of plasticity.\n\nB controls the balance between potentiation and depression. It must be in the range [-1, 1]:\n\nB = 1: pure potentiation\nB = -1: pure depression\nB = 0: balanced potentiation and depression\n\nαpre and αpost are the rate constants applied at each pre- and postsynaptic spike, respectively.\n\nτ_plus sets the time constant of the positive traces.\n\nγ sets the relative time constant of the negative traces, γ τ_plus.\n\nUpdated weights are restricted to the interval [weight_min, weight_max].\n\n\n\n\n\n","title":"HawkesPlasticNetworks.PlasticitySymmetricSTDP"},{"category":"type","location":"#HawkesPlasticNetworks.PlasticityVogelsSprekeler","page":"Home","text":"PlasticityVogelsSprekeler(\n    η::Real, r_target::Real,\n    τ::Real,\n    weights::Matrix{Float64};\n    weight_min::Real=0.0, weight_max::Real=Inf)\n\nConstructs the symmetric Vogels-Spreckeler inhibitory homeostatic rule for weights. Positions that are exactly zero at construction are not changed by plasticity. Use refresh_mask! to update the plastic synapses.\n\nη is the global learning rate: it scales all terms of plasticity\n\nr_target is the postsynaptic target firing rate\n\nτ sets the time constant\n\nFor a presynaptic spike, the synaptic increment is η*(-r_target + 0.5*trace_post). For a postsynaptic spike, it is η*0.5*trace_pre. Because traces are normalized to have a mean equal to the corresponding firing rate, independent Poisson spike trains have expected drift η*(-r_target*r_pre + r_pre*r_post).\n\n\n\n\n\n","title":"HawkesPlasticNetworks.PlasticityVogelsSprekeler"},{"category":"method","location":"#HawkesPlasticNetworks.apply_plasticity!-Tuple{Real, Symbol, Integer, Tuple}","page":"Home","text":"apply_plasticity!(t_fire, population_fire_label, neuron_fire_idx,\n                  connected_populations)\n\nApply every plasticity rule on every connection after a neuron fires.\n\nRules implement apply_plasticity!(rule, connection, t_fire, population_fire_label, neuron_fire_idx). The tuple recursion keeps the concrete connection and rule types visible to the compiler and does not allocate intermediate collections.\n\n\n\n\n\n","title":"HawkesPlasticNetworks.apply_plasticity!"},{"category":"method","location":"#HawkesPlasticNetworks.expected_rate_EI-NTuple{6, Real}","page":"Home","text":"expected_rate_EI(\n    w_ee::Real,w_ie::Real,\n    w_ei::Real,w_ii::Real,\n    h_e::Real,h_i::Real)\n\nComputes the expected firing rates for a two population EI network Weight arguments are in absolute value. Assumes this linear dynamics.\n\nτ dre/dt = -re + (wee re - wei ri + he) τ dri/dt = -ri + (wie re - wii ri + hi)\n\nSo the solution is (Id-Wmat)^-1 * hvec.\n\nReturns: re,ri\n\n\n\n\n\n","title":"HawkesPlasticNetworks.expected_rate_EI"},{"category":"function","location":"#HawkesPlasticNetworks.generate_sparse_matrix_fixed_input","page":"Home","text":"generatesparsematrixfixedinput(npost::Integer,npre::Integer,    w::Real,p::Real=0.1; self_connections::Bool=true)\n\nGenerate a sparse matrix, with density p so that each row sums to w. An ArgumentError is thrown if the sampled connectivity contains a row or column with no connections.\n\nArguments:\n\nn_post::Integer: number of postsynaptic neurons\nn_pre::Integer: number of presynaptic neurons\nw::Real: weight of each connection\np::Real: probability of each connection\nself_connections::Bool: whether to include self-connections\n\nReturns:\n\nw::Matrix{Float64}: weight matrix\n\n\n\n\n\n","title":"HawkesPlasticNetworks.generate_sparse_matrix_fixed_input"},{"category":"method","location":"#HawkesPlasticNetworks.plasticity_off!-Tuple{HawkesPlasticNetworks.AbstractConnectionWithWeights}","page":"Home","text":"plasticity_off!(connection)\n\nDeactivate plasticity for a connection (all rules included).\n\n\n\n\n\n","title":"HawkesPlasticNetworks.plasticity_off!"},{"category":"method","location":"#HawkesPlasticNetworks.plasticity_on!-Tuple{HawkesPlasticNetworks.AbstractConnectionWithWeights}","page":"Home","text":"plasticity_on!(connection)\n\nActivate plasticity for a connection (all rules included).\n\n\n\n\n\n","title":"HawkesPlasticNetworks.plasticity_on!"},{"category":"method","location":"#HawkesPlasticNetworks.refresh_mask!-Tuple{HawkesPlasticNetworks.AbstractPlasticitySTDP, Matrix{Float64}}","page":"Home","text":"refresh_mask!(plasticity, weights)\n\nReplace the structural-zero mask with the positions that are exactly zero in weights. The matrix shape must match the shape used to construct the rule.\n\n\n\n\n\n","title":"HawkesPlasticNetworks.refresh_mask!"},{"category":"method","location":"#HawkesPlasticNetworks.scale_rows_to_sum!-Tuple{AbstractMatrix{Float64}, Real}","page":"Home","text":"scalerowstosum!(mat::AbstractMatrix{Float64},rowsum::Real)\n\nScales each row of mat so that the row sums to row_sum. (this corresponds to scaling all incoming weights) Throws an error if any row is zero.\n\n\n\n\n\n","title":"HawkesPlasticNetworks.scale_rows_to_sum!"}]
}
